#include <bits/stdc++.h>
using namespace std;

int main() {
    const long long MOD = 1'000'000'007;
    vector<int> coins = {1, 2, 5};
    int target = 5;

    vector<long long> comb(target + 1, 0);   // 순서 무관: 동전이 바깥 반복
    comb[0] = 1;
    for (int c : coins)
        for (int x = c; x <= target; x++)
            comb[x] = (comb[x] + comb[x - c]) % MOD;

    vector<long long> seq(target + 1, 0);    // 순서 있음: 금액이 바깥 반복
    seq[0] = 1;
    for (int x = 1; x <= target; x++)
        for (int c : coins)
            if (c <= x) seq[x] = (seq[x] + seq[x - c]) % MOD;

    for (int x = 0; x <= target; x++) cout << comb[x] << (x == target ? '\n' : ' ');
    for (int x = 0; x <= target; x++) cout << seq[x] << (x == target ? '\n' : ' ');
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<pair<int, int>> items = {{3, 4}, {4, 5}, {2, 3}};   // (무게, 가치)
    int W = 6;

    vector<int> once(W + 1, 0);               // 물건마다 한 번만
    for (auto [w, v] : items)
        for (int c = W; c >= w; c--)          // 큰 용량부터
            once[c] = max(once[c], once[c - w] + v);

    vector<int> many(W + 1, 0);               // 같은 물건 여러 번 가능
    for (auto [w, v] : items)
        for (int c = w; c <= W; c++)          // 작은 용량부터
            many[c] = max(many[c], many[c - w] + v);

    for (int c = 0; c <= W; c++) cout << once[c] << (c == W ? '\n' : ' ');
    for (int c = 0; c <= W; c++) cout << many[c] << (c == W ? '\n' : ' ');
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

string a = "GXTXAYB", b = "AGGTAB";
vector<vector<int>> memo;

int lcs(int i, int j) {                       // a[i..], b[j..] 의 LCS 길이
    if (i == (int)a.size() || j == (int)b.size()) return 0;
    int& r = memo[i][j];
    if (r != -1) return r;                    // 이미 계산함
    if (a[i] == b[j]) return r = lcs(i + 1, j + 1) + 1;
    return r = max(lcs(i + 1, j), lcs(i, j + 1));
}

int main() {
    int n = a.size(), m = b.size();
    memo.assign(n, vector<int>(m, -1));

    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));   // a[:i], b[:j]
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
            dp[i][j] = (a[i - 1] == b[j - 1]) ? dp[i - 1][j - 1] + 1
                                              : max(dp[i - 1][j], dp[i][j - 1]);

    cout << lcs(0, 0) << ' ' << dp[n][m] << '\n';
    return 0;
}
